import { readAppearance, resolveAppearance, saveAppearance } from './appearance.mjs';
const app=document.querySelector('#app');const root=document.documentElement;const toast=document.querySelector('#toast');let timer;
function notice(message){toast.textContent=message;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2400)}
const media=window.matchMedia('(prefers-color-scheme: dark)');let appearance=readAppearance(localStorage);const menu=document.querySelector('#appearanceMenu');const themeButton=document.querySelector('[data-action=theme]');function applyAppearance(){root.dataset.theme=resolveAppearance(appearance,media.matches);document.querySelectorAll('[data-appearance]').forEach(button=>{const selected=button.dataset.appearance===appearance;button.querySelector('span').textContent=selected?'✓':'';button.setAttribute('aria-pressed',String(selected))})}applyAppearance();media.addEventListener('change',()=>{if(appearance==='system')applyAppearance()});
document.addEventListener('click',async(e)=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.appearance){appearance=button.dataset.appearance;const saved=saveAppearance(localStorage,appearance);applyAppearance();menu.hidden=true;themeButton.setAttribute('aria-expanded','false');if(!saved)notice('无法保存外观设置，本次仍可使用');return}if(button.dataset.toast){notice(button.dataset.toast);return}switch(button.dataset.action){case'theme':menu.hidden=!menu.hidden;themeButton.setAttribute('aria-expanded',String(!menu.hidden));break;case'preview':app.classList.toggle('preview-closed');app.classList.remove('preview-expanded');break;case'open-preview':app.classList.remove('preview-closed');break;case'sidebar':app.classList.toggle('sidebar-closed');break;case'expand':app.classList.toggle('preview-expanded');break;case'step':{const d=button.nextElementSibling;d.hidden=!d.hidden;button.querySelector('.step-arrow').textContent=d.hidden?'⌄':'⌃';break}case'tab':document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===button));document.querySelector('#document').hidden=button.dataset.tab!=='preview';document.querySelector('#source').hidden=button.dataset.tab!=='source';break;case'attach':document.querySelector('#fileInput').click();break;case'model':notice('模型选择为界面示例');break;case'copy':case'copy-file':try{await navigator.clipboard.writeText(button.dataset.action==='copy-file'?document.querySelector('#source').textContent:document.querySelector('.response').innerText);notice('已复制到剪贴板')}catch{notice('当前环境无法访问剪贴板')}break;case'new':notice('这是视觉原型，新建任务将在后续接入');break}});
document.querySelector('#fileInput').addEventListener('change',e=>{document.querySelector('#attached').textContent=e.target.files[0]?.name||''});document.querySelector('#composer').addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#input');const value=input.value.trim();if(!value)return;const msg=document.createElement('div');msg.className='added-message';msg.textContent=value;document.querySelector('#newMessages').append(msg);input.value='';document.querySelector('#chatScroll').scrollTo({top:document.querySelector('#chatScroll').scrollHeight,behavior:'smooth'});notice('视觉原型：消息已展示，暂未连接模型')});document.querySelector('#input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('#composer').requestSubmit()}});

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){menu.hidden=true;themeButton.setAttribute('aria-expanded','false');themeButton.focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('.appearance-control')){menu.hidden=true;themeButton.setAttribute('aria-expanded','false')}});
